import React, { useState, useMemo, useRef, useCallback } from "react";

/**
 * ISD — Interactive Leasing Map  (Editor + Viewer)
 *
 * RENT MODEL  — each zone has a structured `rent`:
 *   { type: "fixed",      base }            → base
 *   { type: "greater_of", base, pct }       → max(base, pct% × revenue)
 *   { type: "fixed_plus", base, pct }       → base + pct% × revenue
 *  `tenantRevenue` (optional, per zone) lets the map compute the
 *   EFFECTIVE rent and which leg wins. Without it, % contracts show the
 *   formula, not a fake number. Legacy zones with a flat `rentYear`
 *   still work (auto-coerced to a fixed contract).
 *
 * COLOUR  per-zone `color` overrides; else falls back to status colour.
 * NESTED  zones hit-tested smallest-area-first (inner courts clickable).
 * COORDS  normalized 0–100 both axes, locked to the photo on resize.
 * DATA    ZONES below is the single swap point → Sheets / API.
 */

