const STATUS = {
  under_isd:           { label: "Under ISD",             color: "#2E9E6B" },
  under_isd_subleased: { label: "Under ISD – Subleased", color: "#C9A227" },
  not_under_isd:       { label: "Not under ISD",         color: "#6B7280" },
};

const RENT_TYPES = {
  fixed:       { label: "Fixed" },
  greater_of:  { label: "Greater of (base or %)" },
  fixed_plus:  { label: "Base + %" },
};

const PALETTE = [
  "#2E9E6B", "#C9A227", "#6B7280", "#3B82F6", "#E0533D",
  "#9B59B6", "#14B8A6", "#B45309", "#EC4899", "#F4F2ED",
];

const zoneColor = (z) => z.color || STATUS[z.status]?.color || "#C9A227";

const rgba = (hex, a) => {
  const h = hex.replace("#", "");
  return `rgba(${parseInt(h.slice(0, 2), 16)},${parseInt(h.slice(2, 4), 16)},${parseInt(h.slice(4, 6), 16)},${a})`;
};

const AED = (n) => new Intl.NumberFormat("en-AE", { maximumFractionDigits: 0 }).format(n);

const BASEMAP = "data:image/jpeg;base64,";

// normalize a zone's rent (handles legacy flat rentYear)
const getRent = (z) => {
  if (z.rent) return z.rent;
  return { type: "fixed", base: z.rentYear || 0, pct: 0 };
};

// human-readable formula, revenue-independent
const rentFormula = (rent) => {
  const b = `AED ${AED(rent.base || 0)}`;
  if (rent.type === "fixed") return b;
  if (rent.type === "greater_of") return `${b}  OR  ${rent.pct || 0}% of revenue — whichever is higher`;
  if (rent.type === "fixed_plus") return `${b}  +  ${rent.pct || 0}% of revenue`;
  return b;
};

// effective rent given a revenue; returns {value, leg, determined}
const effectiveRent = (rent, revenue) => {
  const base = rent.base || 0;
  const pctAmt = ((rent.pct || 0) / 100) * (revenue || 0);
  if (rent.type === "fixed")
    return { value: base, leg: "fixed", determined: true };
  if (rent.type === "greater_of") {
    if (!revenue) return { value: base, leg: "min-base", determined: false };
    const win = pctAmt > base;
    return { value: Math.max(base, pctAmt), leg: win ? "percent" : "base", determined: true };
  }
  if (rent.type === "fixed_plus") {
    if (!revenue) return { value: base, leg: "base-only", determined: false };
    return { value: base + pctAmt, leg: "base+percent", determined: true };
  }
  return { value: base, leg: "fixed", determined: true };
};

const area = (pts) => {
  let a = 0;
  for (let i = 0; i < pts.length; i++) {
    const [x1, y1] = pts[i];
    const [x2, y2] = pts[(i + 1) % pts.length];
    a += x1 * y2 - x2 * y1;
  }
  return Math.abs(a) / 2;
};
const byAreaDesc = (list) => [...list].sort((a, b) => area(b.points) - area(a.points));

