// ─────────────────────────────────────────────────────────────
// VIEWER
// ─────────────────────────────────────────────────────────────
function Viewer() {
  const [hoverId, setHoverId] = useState(null);
  const [selectedId, setSelectedId] = useState(null);
  const activeId = selectedId || hoverId;
  const ordered = useMemo(() => byAreaDesc(ZONES), []);
  // rent/m² for a zone (effective value or floor) — used for sorting + display
  const perSqmValue = (z) => {
    const eff = effectiveRent(getRent(z), z.tenantRevenue);
    return z.sqm > 0 ? eff.value / z.sqm : 0;
  };
  const listOrder = useMemo(
    () => [...ZONES].sort((a, b) => perSqmValue(b) - perSqmValue(a)),
    []
  );
  const active = useMemo(() => ZONES.find((z) => z.id === activeId) || null, [activeId]);

  // compact rent/m² for the list: {text, estimate}
  const perSqmShort = (z) => {
    const rent = getRent(z);
    const eff = effectiveRent(rent, z.tenantRevenue);
    if (!z.sqm) return { text: "—", estimate: false };
    return { text: `AED ${AED(eff.value / z.sqm)}`, estimate: !eff.determined };
  };

  return (
    <div className="lm-view-grid">
      {/* ZONE LIST */}
      <div className="lm-list" style={{ background: "#141922", border: "1px solid #20262F", borderRadius: 14, padding: 14 }}>
        <div className="lm-list-head" style={{ fontSize: 11, letterSpacing: 1.5, color: "#8A93A0", textTransform: "uppercase", marginBottom: 10 }}>Zones ({ZONES.length}) · by rent/m²</div>
        {listOrder.map((z) => {
          const ps = perSqmShort(z);
          const isActive = z.id === activeId;
          return (
            <div key={z.id} className="lm-list-row"
              onMouseEnter={() => setHoverId(z.id)} onMouseLeave={() => setHoverId(null)}
              onClick={() => setSelectedId(selectedId === z.id ? null : z.id)}
              style={{ padding: "9px 10px", borderRadius: 8, cursor: "pointer", marginBottom: 4,
                background: isActive ? "#1C2530" : "transparent",
                borderLeft: `3px solid ${isActive ? zoneColor(z) : "transparent"}` }}>
              <div style={{ display: "flex", alignItems: "center", gap: 7, marginBottom: 3 }}>
                <span style={{ width: 8, height: 8, borderRadius: 2, background: zoneColor(z), flexShrink: 0 }} />
                <span style={{ fontSize: 13, color: "#E8E6E1", fontWeight: 500, whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>{z.name}</span>
              </div>
              <div style={{ display: "flex", justifyContent: "space-between", fontSize: 11, color: "#8A93A0", paddingLeft: 15 }}>
                <span>{AED(z.sqm)} m²</span>
                <span style={{ fontVariantNumeric: "tabular-nums" }}>{ps.text}{ps.estimate ? "*" : ""}/m²</span>
              </div>
            </div>
          );
        })}
        <div className="lm-list-foot" style={{ fontSize: 10, color: "#6B7280", marginTop: 8, paddingLeft: 2, lineHeight: 1.4 }}>* floor — depends on tenant revenue</div>
      </div>

      <div style={{ position: "relative", borderRadius: 14, overflow: "hidden", border: "1px solid #20262F", boxShadow: "0 18px 50px rgba(0,0,0,.45)", lineHeight: 0 }}>
        <img src={BASEMAP} alt="Site" style={{ width: "100%", display: "block" }} />
        <svg viewBox="0 0 100 100" preserveAspectRatio="none" style={{ position: "absolute", inset: 0, width: "100%", height: "100%" }}>
          {ordered.map((z) => {
            const isActive = z.id === activeId;
            const c = zoneColor(z);
            return (
              <polygon key={z.id} className="lm-zone"
                points={z.points.map((p) => p.join(",")).join(" ")}
                onMouseEnter={() => setHoverId(z.id)} onMouseLeave={() => setHoverId(null)}
                onClick={() => setSelectedId(selectedId === z.id ? null : z.id)}
                style={{ cursor: "pointer", fill: rgba(c, isActive ? 0.40 : 0.16), stroke: c, strokeWidth: isActive ? 0.7 : 0.4, vectorEffect: "non-scaling-stroke" }}
              />
            );
          })}
        </svg>
        <div style={{ position: "absolute", left: 12, bottom: 12, display: "flex", gap: 14, background: "rgba(14,17,22,.82)", padding: "8px 12px", borderRadius: 8, fontSize: 11, border: "1px solid #2A313B" }}>
          {Object.entries(STATUS).map(([k, v]) => (
            <span key={k} style={{ display: "flex", alignItems: "center", gap: 6 }}>
              <span style={{ width: 8, height: 8, borderRadius: 2, background: v.color, display: "inline-block" }} />{v.label}
            </span>
          ))}
        </div>
      </div>

      <div style={{ background: "#141922", border: "1px solid #20262F", borderRadius: 14, padding: 20, minHeight: 300 }}>
        {!active ? (
          <div style={{ color: "#6B7280", fontSize: 14, paddingTop: 30, textAlign: "center" }}>Select a zone to see metrics</div>
        ) : (() => {
          const rent = getRent(active);
          const eff = effectiveRent(rent, active.tenantRevenue);
          const perSqm = active.sqm > 0 ? eff.value / active.sqm : 0;
          const legLabel = {
            "percent": "% leg applies", "base": "base applies", "min-base": "base (floor)",
            "base-only": "base only", "base+percent": "base + %", "fixed": "fixed",
          }[eff.leg];
          return (
            <>
              <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 4 }}>
                <span style={{ width: 9, height: 9, borderRadius: 2, background: zoneColor(active) }} />
                <span style={{ fontSize: 11, letterSpacing: 1.5, color: "#8A93A0", textTransform: "uppercase" }}>{STATUS[active.status]?.label || active.status}</span>
              </div>
              <h2 style={{ fontFamily: "'Fraunces', serif", fontSize: 22, fontWeight: 600, margin: "0 0 16px", color: "#F4F2ED" }}>{active.name}</h2>

              <Metric label="Area" value={`${AED(active.sqm)} m²`} />

              {/* Rent structure */}
              <div style={{ padding: "12px 0", borderTop: "1px solid #20262F" }}>
                <div style={{ fontSize: 13, color: "#8A93A0", marginBottom: 4 }}>Rent terms</div>
                <div style={{ fontSize: 13, color: "#E8E6E1", lineHeight: 1.5 }}>{rentFormula(rent)}</div>
              </div>

              {/* Effective rent */}
              <div style={{ padding: "12px 0", borderTop: "1px solid #20262F", display: "flex", justifyContent: "space-between", alignItems: "baseline" }}>
                <span style={{ fontSize: 13, color: "#8A93A0" }}>
                  {eff.determined ? "Effective rent / year" : "Min rent / year"}
                  {eff.determined && legLabel ? <span style={{ color: "#6B7280" }}> · {legLabel}</span> : null}
                </span>
                <span style={{ fontSize: 18, fontWeight: 600, color: "#C9A227", fontVariantNumeric: "tabular-nums" }}>AED {AED(eff.value)}</span>
              </div>

              {/* Rent per sqm — honest about determinacy */}
              <div style={{ padding: "12px 0", borderTop: "1px solid #20262F", display: "flex", justifyContent: "space-between", alignItems: "baseline" }}>
                <span style={{ fontSize: 13, color: "#8A93A0" }}>Rent / m² / year</span>
                <span style={{ fontSize: 15, fontWeight: 600, color: "#E8E6E1", fontVariantNumeric: "tabular-nums", textAlign: "right" }}>
                  AED {AED(perSqm)}
                  {!eff.determined && <div style={{ fontSize: 10, color: "#B45309", fontWeight: 500 }}>floor — depends on revenue</div>}
                </span>
              </div>

              {rent.type !== "fixed" && (
                <div style={{ marginTop: 4, fontSize: 11, color: "#6B7280", lineHeight: 1.5 }}>
                  {active.tenantRevenue ? `Based on tenant revenue AED ${AED(active.tenantRevenue)}.` : "Set tenant revenue (Edit mode) to compute the % leg."}
                </div>
              )}
            </>
          );
        })()}
      </div>
    </div>
  );
}

// ─────────────────────────────────────────────────────────────
// EDITOR
// ─────────────────────────────────────────────────────────────
function Editor() {
  const [zones, setZones] = useState(() =>
    ZONES.map((z) => ({ ...z, rent: { ...getRent(z) }, points: z.points.map((p) => [...p]) }))
  );
  const [draft, setDraft] = useState([]);
  const [selectedId, setSelectedId] = useState(null);
  const [copied, setCopied] = useState(false);
  const [drawing, setDrawing] = useState(false); // when true, clicks add points even over existing zones
  const svgRef = useRef(null);

  const toCoord = useCallback((e) => {
    const r = svgRef.current.getBoundingClientRect();
    const x = ((e.clientX - r.left) / r.width) * 100;
    const y = ((e.clientY - r.top) / r.height) * 100;
    return [Math.round(x * 10) / 10, Math.round(y * 10) / 10];
  }, []);

  const addPoint = (e) => { if (drawing) setDraft((d) => [...d, toCoord(e)]); };
  const undoPoint = () => setDraft((d) => d.slice(0, -1));

  const finishZone = () => {
    if (draft.length < 3) return;
    const z = {
      id: `Z${Date.now() % 100000}`, name: `Zone ${zones.length + 1}`,
      sqm: 0, rent: { type: "fixed", base: 0, pct: 0 }, tenantRevenue: 0,
      status: "under_isd", color: STATUS.under_isd.color, points: draft,
    };
    setZones((zs) => [...zs, z]); setSelectedId(z.id); setDraft([]); setDrawing(false);
  };

  const updateZone = (id, patch) => setZones((zs) => zs.map((z) => (z.id === id ? { ...z, ...patch } : z)));
  const updateRent = (id, patch) => setZones((zs) => zs.map((z) => (z.id === id ? { ...z, rent: { ...getRent(z), ...patch } } : z)));
  const deleteZone = (id) => { setZones((zs) => zs.filter((z) => z.id !== id)); if (selectedId === id) setSelectedId(null); };

  const exportText = useMemo(() => {
    const body = zones.map((z) => {
      const pts = z.points.map((p) => `[${p[0]}, ${p[1]}]`).join(", ");
      const r = getRent(z);
      const rentStr = r.type === "fixed"
        ? `{ type: "fixed", base: ${r.base || 0} }`
        : `{ type: "${r.type}", base: ${r.base || 0}, pct: ${r.pct || 0} }`;
      return `  {\n    id: "${z.id}",\n    name: ${JSON.stringify(z.name)},\n    sqm: ${z.sqm || 0},\n    rent: ${rentStr},\n    tenantRevenue: ${z.tenantRevenue || 0},\n    status: "${z.status}",\n    color: "${zoneColor(z)}",\n    points: [${pts}],\n  },`;
    }).join("\n");
    return `const ZONES = [\n${body}\n];`;
  }, [zones]);

  const copyExport = async () => {
    try { await navigator.clipboard.writeText(exportText); } catch { /* textarea fallback */ }
    setCopied(true); setTimeout(() => setCopied(false), 1600);
  };

  const ordered = byAreaDesc(zones);
  const selected = zones.find((z) => z.id === selectedId) || null;
  const selRent = selected ? getRent(selected) : null;
  const selEff = selected ? effectiveRent(selRent, selected.tenantRevenue) : null;

  return (
    <div className="lm-edit-grid">
      <div>
        <div style={{ position: "relative", borderRadius: 14, overflow: "hidden", border: "1px solid #20262F", boxShadow: "0 18px 50px rgba(0,0,0,.45)", lineHeight: 0 }}>
          <img src={BASEMAP} alt="Site" style={{ width: "100%", display: "block", userSelect: "none" }} draggable={false} />
          <svg ref={svgRef} viewBox="0 0 100 100" preserveAspectRatio="none"
            onClick={addPoint} onDoubleClick={(e) => { e.preventDefault(); finishZone(); }}
            style={{ position: "absolute", inset: 0, width: "100%", height: "100%", cursor: drawing ? "crosshair" : "default" }}>
            {ordered.map((z) => {
              const c = zoneColor(z);
              return (
                <polygon key={z.id} points={z.points.map((p) => p.join(",")).join(" ")}
                  onClick={(e) => { if (!drawing) { e.stopPropagation(); setSelectedId(z.id); } }}
                  style={{ fill: rgba(c, z.id === selectedId ? 0.34 : 0.14), stroke: c, strokeWidth: z.id === selectedId ? 0.7 : 0.4, vectorEffect: "non-scaling-stroke", cursor: drawing ? "crosshair" : "pointer", pointerEvents: drawing ? "none" : "auto" }}
                />
              );
            })}
            {draft.length > 0 && (
              <>
                <polyline points={draft.map((p) => p.join(",")).join(" ")}
                  style={{ fill: "rgba(244,242,237,.12)", stroke: "#F4F2ED", strokeWidth: 0.6, strokeDasharray: "1.5 1", vectorEffect: "non-scaling-stroke", pointerEvents: "none" }} />
                {draft.map((p, i) => (
                  <circle key={i} cx={p[0]} cy={p[1]} r="0.8" style={{ fill: i === 0 ? "#C9A227" : "#F4F2ED", stroke: "#0E1116", strokeWidth: 0.25, vectorEffect: "non-scaling-stroke", pointerEvents: "none" }} />
                ))}
              </>
            )}
          </svg>
        </div>
        <div style={{ display: "flex", gap: 8, marginTop: 12, flexWrap: "wrap", alignItems: "center" }}>
          <button className={`lm-btn ${drawing ? "active" : ""}`} onClick={() => setDrawing((d) => !d)}>
            {drawing ? "✏ Drawing… (click to place)" : "+ Draw zone"}
          </button>
          <span style={{ fontSize: 13, color: "#8A93A0" }}>
            {drawing ? `double-click to finish · ${draft.length} pts` : "turn on to draw, incl. inside another zone"}
          </span>
          <div style={{ flex: 1 }} />
          <button className="lm-btn" onClick={undoPoint} disabled={!draft.length} style={{ opacity: draft.length ? 1 : 0.45 }}>Undo point</button>
          <button className="lm-btn" onClick={() => setDraft([])} disabled={!draft.length} style={{ opacity: draft.length ? 1 : 0.45 }}>Clear draft</button>
          <button className="lm-btn active" onClick={finishZone} disabled={draft.length < 3} style={{ opacity: draft.length < 3 ? 0.45 : 1 }}>Finish zone</button>
        </div>
      </div>

      <div style={{ display: "flex", flexDirection: "column", gap: 16 }}>
        <div style={{ background: "#141922", border: "1px solid #20262F", borderRadius: 14, padding: 16 }}>
          <div style={{ fontSize: 11, letterSpacing: 1.5, color: "#8A93A0", textTransform: "uppercase", marginBottom: 10 }}>Zones ({zones.length})</div>
          {zones.length === 0 && <div style={{ color: "#6B7280", fontSize: 13 }}>None yet — draw one on the map.</div>}
          {zones.map((z) => (
            <div key={z.id} onClick={() => setSelectedId(z.id)} style={{ display: "flex", alignItems: "center", gap: 8, padding: "7px 8px", borderRadius: 7, cursor: "pointer", background: z.id === selectedId ? "#1C2530" : "transparent" }}>
              <span style={{ width: 8, height: 8, borderRadius: 2, background: zoneColor(z) }} />
              <span style={{ fontSize: 13, flex: 1, color: "#E8E6E1", whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>{z.name}</span>
              <span onClick={(e) => { e.stopPropagation(); deleteZone(z.id); }} style={{ fontSize: 16, color: "#6B7280", cursor: "pointer", lineHeight: 1 }}>×</span>
            </div>
          ))}
        </div>

        {selected && (
          <div style={{ background: "#141922", border: "1px solid #20262F", borderRadius: 14, padding: 16 }}>
            <div style={{ fontSize: 11, letterSpacing: 1.5, color: "#8A93A0", textTransform: "uppercase", marginBottom: 8 }}>Edit zone</div>
            <label style={{ fontSize: 12, color: "#8A93A0" }}>Name
              <input className="lm-input" value={selected.name} onChange={(e) => updateZone(selected.id, { name: e.target.value })} />
            </label>
            <label style={{ fontSize: 12, color: "#8A93A0", display: "block", marginTop: 10 }}>Area (m²)
              <input className="lm-input" type="number" value={selected.sqm || ""} onChange={(e) => updateZone(selected.id, { sqm: Number(e.target.value) })} />
            </label>

            {/* Rent structure */}
            <label style={{ fontSize: 12, color: "#8A93A0", display: "block", marginTop: 10 }}>Rent type
              <select className="lm-input" value={selRent.type} onChange={(e) => updateRent(selected.id, { type: e.target.value })}>
                {Object.entries(RENT_TYPES).map(([k, v]) => <option key={k} value={k}>{v.label}</option>)}
              </select>
            </label>
            <label style={{ fontSize: 12, color: "#8A93A0", display: "block", marginTop: 10 }}>Base rent / year (AED)
              <input className="lm-input" type="number" value={selRent.base || ""} onChange={(e) => updateRent(selected.id, { base: Number(e.target.value) })} />
            </label>
            {selRent.type !== "fixed" && (
              <>
                <label style={{ fontSize: 12, color: "#8A93A0", display: "block", marginTop: 10 }}>% of revenue
                  <input className="lm-input" type="number" value={selRent.pct || ""} onChange={(e) => updateRent(selected.id, { pct: Number(e.target.value) })} />
                </label>
                <label style={{ fontSize: 12, color: "#8A93A0", display: "block", marginTop: 10 }}>Tenant revenue / year (AED) — optional
                  <input className="lm-input" type="number" value={selected.tenantRevenue || ""} onChange={(e) => updateZone(selected.id, { tenantRevenue: Number(e.target.value) })} />
                </label>
              </>
            )}

            {/* live effective rent preview */}
            <div style={{ marginTop: 12, padding: "10px 12px", background: "#0E1116", borderRadius: 8, border: "1px solid #20262F" }}>
              <div style={{ fontSize: 11, color: "#8A93A0", marginBottom: 4 }}>{rentFormula(selRent)}</div>
              <div style={{ fontSize: 14, fontWeight: 600, color: "#C9A227" }}>
                {selEff.determined ? "Effective" : "Min"}: AED {AED(selEff.value)}
                {selected.sqm > 0 && <span style={{ color: "#8A93A0", fontWeight: 500, fontSize: 12 }}> · {AED(selEff.value / selected.sqm)}/m²{!selEff.determined ? " (floor)" : ""}</span>}
              </div>
            </div>

            <label style={{ fontSize: 12, color: "#8A93A0", display: "block", marginTop: 12 }}>Status
              <select className="lm-input" value={selected.status} onChange={(e) => updateZone(selected.id, { status: e.target.value })}>
                {Object.entries(STATUS).map(([k, v]) => <option key={k} value={k}>{v.label}</option>)}
              </select>
            </label>

            <div style={{ fontSize: 12, color: "#8A93A0", marginTop: 12, marginBottom: 6 }}>Colour</div>
            <div style={{ display: "flex", flexWrap: "wrap", gap: 7, alignItems: "center" }}>
              {PALETTE.map((c) => (
                <span key={c} className={`lm-swatch ${zoneColor(selected) === c ? "sel" : ""}`} style={{ background: c }} onClick={() => updateZone(selected.id, { color: c })} />
              ))}
              <label style={{ display: "inline-flex", alignItems: "center", gap: 6, marginLeft: 4, fontSize: 11, color: "#8A93A0" }}>
                <input type="color" value={zoneColor(selected)} onChange={(e) => updateZone(selected.id, { color: e.target.value })}
                  style={{ width: 26, height: 26, padding: 0, border: "1px solid #2A313B", borderRadius: 6, background: "transparent", cursor: "pointer" }} />
                custom
              </label>
              <button className="lm-btn" style={{ padding: "4px 8px", fontSize: 11 }} onClick={() => updateZone(selected.id, { color: STATUS[selected.status]?.color })}>Reset to status</button>
            </div>
          </div>
        )}

        <div style={{ background: "#141922", border: "1px solid #20262F", borderRadius: 14, padding: 16 }}>
          <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 8 }}>
            <span style={{ fontSize: 11, letterSpacing: 1.5, color: "#8A93A0", textTransform: "uppercase" }}>Export</span>
            <button className="lm-btn" onClick={copyExport}>{copied ? "Copied ✓" : "Copy"}</button>
          </div>
          <div style={{ fontSize: 12, color: "#8A93A0", marginBottom: 8 }}>Paste this over the <code>ZONES</code> array in App.jsx.</div>
          <textarea readOnly value={exportText} className="lm-input" style={{ height: 140, fontFamily: "ui-monospace, monospace", fontSize: 11, resize: "vertical" }} />
        </div>
      </div>
    </div>
  );
}

function Metric({ label, value, accent }) {
  return (
    <div style={{ padding: "12px 0", borderTop: "1px solid #20262F", display: "flex", justifyContent: "space-between", alignItems: "baseline" }}>
      <span style={{ fontSize: 13, color: "#8A93A0" }}>{label}</span>
      <span style={{ fontSize: accent ? 18 : 15, fontWeight: 600, color: accent ? "#C9A227" : "#E8E6E1", fontVariantNumeric: "tabular-nums" }}>{value}</span>
    </div>
  );
}
